import { LOCATIONS, type Location } from './locations';
import { Time, type TimeJson } from './Time';

export interface SectionJson {
  startTime: TimeJson;
  endTime: TimeJson;
  location?: string;
}

export class Section {
  startTime: Time;
  endTime: Time;
  location: Location;

  constructor(
    startTime: Time,
    endTime: Time,
    location: Location = LOCATIONS.UNASSIGNED,
  ) {
    this.startTime = startTime;
    this.endTime = endTime;
    this.location = location;
  }

  formattedString(): string {
    const timeRange = `${this.startTime.formattedString()} - ${this.endTime.formattedString()}`;
    return `${timeRange} (${this.location})`;
  }

  durationInMinutes(): number {
    return this.endTime.inMinutes() - this.startTime.inMinutes();
  }

  toJSON(): SectionJson {
    return {
      startTime: this.startTime.toJSON(),
      endTime: this.endTime.toJSON(),
      location: this.location,
    };
  }

  static fromJSON(s: SectionJson): Section {
    return new Section(
      Time.fromJSON(s.startTime),
      Time.fromJSON(s.endTime),
      (s.location as Location | undefined) ?? LOCATIONS.UNASSIGNED,
    );
  }
}
